const body = $json.body ?? $json;
const presets = [
  { template_name: 'Congestion Study', goal: 'Identify where and when crowding occurs in a monitored space', default_behaviors: ['entry clustering', 'standing clusters', 'queuing', 'high-density occupancy'], recommended_duration: '2 weeks', recommended_outputs: ['peak congestion times', 'zone hotspot chart', 'entry bottleneck summary', 'layout recommendations'], example_user_friendly_explanation: 'Use this when you want to find crowding hotspots and understand when bottlenecks happen.' },
  { template_name: 'Space Utilization Study', goal: 'Understand which zones are underused, overused, or unevenly used over time', default_behaviors: ['occupancy presence', 'seat use', 'linger duration', 'repeat zone use'], recommended_duration: '2 to 4 weeks', recommended_outputs: ['zone utilization chart', 'hourly occupancy trend', 'underused-area summary'], example_user_friendly_explanation: 'Use this to see which areas people actually use and which layouts are being ignored.' },
  { template_name: 'Interaction / Collaboration Study', goal: 'Identify where collaboration and small-group interaction naturally emerge', default_behaviors: ['small standing groups', 'seated collaboration', 'repeat gathering points'], recommended_duration: '2 weeks', recommended_outputs: ['interaction hotspots', 'time-of-day interaction summary', 'collaboration zone ranking'], example_user_friendly_explanation: 'Use this to see where groups naturally form and whether the space supports collaboration.' },
  { template_name: 'Thermal Comfort Proxy Study', goal: 'Look for visible behaviors that may signal discomfort related to temperature or airflow conditions', default_behaviors: ['layer adjustment', 'restlessness', 'frequent relocation', 'window/door proximity clustering'], recommended_duration: '1 to 2 weeks', recommended_outputs: ['comfort proxy timeline', 'zone discomfort signals', 'possible HVAC/layout follow-ups'], example_user_friendly_explanation: 'Use this when you suspect discomfort but want visible behavior clues before deeper diagnostics.' },
  { template_name: 'Entrance / Flow Study', goal: 'Understand how people move through monitored entry and transition zones', default_behaviors: ['entry surges', 'door hesitation', 'queue formation', 'directional flow imbalance'], recommended_duration: '1 to 2 weeks', recommended_outputs: ['entry flow trend', 'surge windows', 'bottleneck summary', 'wayfinding/layout recommendations'], example_user_friendly_explanation: 'Use this to understand movement patterns, surges, and possible entry bottlenecks.' }
];
return [{ json: { user_id: body.user_id ?? null, session_id: body.session_id ?? null, message_text: body.message_text ?? body.message ?? '', building_id: body.building_id ?? null, study_id: body.study_id ?? null, debug_mode: body.debug_mode ?? false, recommended_presets_catalog: presets, chat_request: body } }];

const item = $input.first().json;
const output = item.output ?? item.text ?? item.response ?? item.data ?? item;
let parsed = output;
const errors = [];

if (typeof parsed === 'string') {
  try { parsed = JSON.parse(parsed); } catch (error) { errors.push('json_parse_failed'); }
}

if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
  errors.push('payload_not_object');
  parsed = {};
}

// Option A fix: normalise common LLM field name shortcuts before validation
if (!parsed.action_type && parsed.action) {
  parsed.action_type = parsed.action;
  delete parsed.action;
}
if (!parsed.target_area && parsed.target_area_or_zone) {
  parsed.target_area = parsed.target_area_or_zone;
  delete parsed.target_area_or_zone;
}

// Only require action_type — assistant_response_text is always filled in by Select Chat Payload
for (const field of ["action_type"]) {
  if (!(field in parsed)) errors.push('missing_' + field);
}

return [{ json: { raw_ai_output: output, parsed_output: parsed, validation_passed: errors.length === 0, validation_errors: errors } }];

const item = $input.first().json;
const output = item.output ?? item.text ?? item.response ?? item.data ?? item;
let parsed = output;
const errors = [];
if (typeof parsed === 'string') {
  try { parsed = JSON.parse(parsed); } catch (error) { errors.push('json_parse_failed'); }
}
if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
  errors.push('payload_not_object');
  parsed = {};
}
for (const field of ["action_type","assistant_response_text"]) {
  if (!(field in parsed)) errors.push('missing_' + field);
}
return [{ json: { raw_ai_output: output, parsed_output: parsed, validation_passed: errors.length === 0, validation_errors: errors } }];

const source = $json.parsed_output ? $json : $items('Validate Chat JSON', 0, 0)[0].json;
const raw = source.raw_ai_output ?? null;
const parsed = { ...(source.parsed_output ?? {}) };

if (!parsed.action_type && parsed.action) parsed.action_type = parsed.action;
if (!parsed.user_goal_summary && parsed.study_goal) parsed.user_goal_summary = parsed.study_goal;

const collected = {
  ...(parsed.collected_fields ?? {}),
  study_goal: parsed.collected_fields?.study_goal ?? parsed.study_goal ?? parsed.setup_request?.study_goal ?? null,
  space_type: parsed.collected_fields?.space_type ?? parsed.space_type ?? parsed.setup_request?.space_type ?? null,
  building_context: parsed.collected_fields?.building_context ?? parsed.building_context ?? null,
  target_area: parsed.collected_fields?.target_area ?? parsed.target_area ?? parsed.setup_request?.target_area ?? null,
  study_duration: parsed.collected_fields?.study_duration ?? parsed.study_duration ?? parsed.setup_request?.study_duration ?? null,
  desired_output_type: parsed.collected_fields?.desired_output_type ?? parsed.desired_output_type ?? parsed.setup_request?.desired_output_type ?? 'occupancy_summary',
  hours_of_interest: parsed.collected_fields?.hours_of_interest ?? parsed.hours_of_interest ?? null,
  known_issues: parsed.collected_fields?.known_issues ?? parsed.known_issues ?? null,
  study_mode: parsed.collected_fields?.study_mode ?? parsed.study_mode ?? null,
  preferred_visualization_type: parsed.collected_fields?.preferred_visualization_type ?? parsed.preferred_visualization_type ?? null,
  business_priority: parsed.collected_fields?.business_priority ?? parsed.priority ?? parsed.business_priority ?? null,
  comparison_baseline: parsed.collected_fields?.comparison_baseline ?? parsed.comparison_baseline ?? null,
};

const required = ['study_goal', 'target_area', 'study_duration'];
const hasSpaceContext = Boolean(collected.space_type || collected.building_context);
const missing = required.filter((field) => !collected[field]);
if (!hasSpaceContext) missing.push('space_type_or_building_context');

if (parsed.action_type === 'start_study') {
  parsed.collected_fields = collected;
  parsed.missing_required_fields = parsed.missing_required_fields?.length ? parsed.missing_required_fields : missing;
  parsed.study_readiness_status = missing.length === 0 ? 'ready' : (parsed.study_readiness_status ?? 'needs_followup');
  parsed.setup_request = parsed.setup_request ?? {};
  parsed.setup_request.study_goal = parsed.setup_request.study_goal ?? collected.study_goal;
  parsed.setup_request.space_type = parsed.setup_request.space_type ?? collected.space_type;
  parsed.setup_request.target_area = parsed.setup_request.target_area ?? collected.target_area;
  parsed.setup_request.study_duration = parsed.setup_request.study_duration ?? collected.study_duration;
  parsed.setup_request.desired_output_type = parsed.setup_request.desired_output_type ?? collected.desired_output_type;
  parsed.setup_request.building_id = parsed.setup_request.building_id ?? $('Normalize Chat Request').item.json.building_id ?? null;
  parsed.setup_request.study_mode = parsed.setup_request.study_mode ?? collected.study_mode ?? 'hypothesis-driven';
}

if (!parsed.assistant_response_text) {
  if (parsed.action_type === 'start_study' && parsed.study_readiness_status === 'ready') {
    parsed.assistant_response_text = 'I have enough information to start this behavior study. I will create the study plan, run needfinding, and begin monitoring through the orchestrator.';
  } else if (parsed.action_type === 'start_study') {
    parsed.assistant_response_text = 'I can help start that study, but I need a little more information first.';
  } else {
    parsed.assistant_response_text = 'I understood the request, but I need one more detail before continuing.';
  }
}

return [{ json: { ...parsed, raw_ai_output: raw } }];

const current = $json;
if (current.study_plan || current.study_status || current.dashboard_summary || current.assistant_response_text) {
  const base = current.assistant_response_text
    ? current
    : (() => {
        if (Array.isArray(current) && current.length > 0) return current[0];
        if (current.study_status) return current;
        return null;
      })();
  if (base) return [{ json: base }];
}
const sourceItems = $input.all().map(i => i.json);
const fallback = sourceItems.find(i => i.assistant_response_text) ?? sourceItems[0] ?? {};
return [{
  json: {
    assistant_response_text: fallback.assistant_response_text ?? 'I could not complete that request safely. Please try again with a study ID or a clearer study goal.',
    action_type: fallback.action_type ?? 'clarify_request',
    study_readiness_status: fallback.study_readiness_status ?? null,
    study_id: fallback.study_id ?? null,
    setup_request: fallback.setup_request ?? null,
    raw_ai_output: fallback.raw_ai_output ?? null,
  }
}];
